public final class BooleanReturnBoundaries {
    private BooleanReturnBoundaries() {}

    public static boolean booleanAsByte(boolean value) { return value; }
    public static boolean booleanAsChar(boolean value) { return value; }
    public static boolean booleanAsShort(boolean value) { return value; }

    public static int integerAsBoolean(int value) { return value; }
}
